import numpy as np, os
OUT='/workspace/work/s2'
os.makedirs(OUT, exist_ok=True)
F = lambda n: 440.0*2**((n-69)/12.0)          # FT2 note number -> Hz  (C-4 = 60 = 261.63)
rate = lambda base: 16.0*F(base)              # renderer model: sample "rate" for base note
def T(dur, base):
    R=rate(base); return np.arange(int(dur*R), dtype=np.float64)/R, R
def osc(x, f, p=1.0, odd=False, tilt=0.0, ph=0.0, maxh=64, sr=16000.0):
    """additive stack limited to 0.45*sr"""
    lim = 0.45*sr
    N = int(min(maxh, lim/f))
    if N<1: N=1
    h=np.arange(1,N+1,dtype=np.float64)
    if odd: h=np.arange(1,N+1,2,dtype=np.float64)
    a=h**(-p)
    if tilt>0: a=a/np.sqrt(1.0+(f*h/tilt)**2)
    out=np.zeros_like(x)
    for i in range(0,len(h),8):
        hb=h[i:i+8]; ab=a[i:i+8]
        out+=np.sin(np.outer(x,f*hb*2*np.pi)+ph*hb*2*np.pi).dot(ab)
    return out
def sine(x,f,amp=1.0,ph=0.0): return amp*np.sin(2*np.pi*f*x+ph)
def nz(n,seed): return np.random.RandomState(seed).randn(n)
def lpf(x,fc):
    X=np.fft.rfft(x); fr=np.fft.rfftfreq(len(x),1.0/ (len(x)/len(x)))  # placeholder
    return x
def filt(x, fc, sr, typ='lp', order=4):
    X=np.fft.rfft(x); fr=np.fft.rfftfreq(len(x),1.0/sr)
    if typ=='lp': H=1.0/(1.0+(fr/fc)**order)
    elif typ=='hp':
        H=1.0/(1.0+(fc/np.maximum(fr,1e-9))**order); H[0]=0
