def band(x, f0, q, sr):
    X=np.fft.rfft(x); fr=np.fft.rfftfreq(len(x),1.0/sr)
    r=np.maximum(fr,1e-9)/f0
    H=1.0/(1.0+((r-1.0/r)**2)*q**2)
    return np.fft.irfft(X*H,n=len(x))
